/**
 * Lumen AI's written weekly review. Generated by the hourly scheduler on the member's Monday,
 * just after their day boundary, for the Monday-to-Sunday week that just ended. Also callable on
 * demand from the app. Only runs for members who turned on AI full access.
 */
import mongoose from 'mongoose';
import { AiWeeklyReport, type IAiWeeklyReportDoc } from '../../../models/AiWeeklyReport';
import { User } from '../../../models/User';
import { DEFAULT_BOUNDARY_HOUR, resolveTimeZone, shiftDayKey, trackingDayKey, weekdayOfKey } from '../../../utils/dayKey';
import { weekKeyOf } from '../../insights/progress';
import { runAssistant } from './assistant';

/** The background job has no one waiting on it, so it may take longer than a chat answer. */
const REVIEW_BUDGET_MS = 120_000;

export function lastFullWeek(todayKey: string): { weekStart: string; weekEnd: string } {
  const weekStart = shiftDayKey(weekKeyOf(todayKey), -7);
  return { weekStart, weekEnd: shiftDayKey(weekStart, 6) };
}

/** True during the member's boundary hour on a Monday (their own time zone). */
export function isWeeklyReviewDue(prefs: { timezone?: string; dayBoundaryHour?: number } | undefined, now: Date): boolean {
  const tz = resolveTimeZone(prefs?.timezone);
  const boundary = prefs?.dayBoundaryHour ?? DEFAULT_BOUNDARY_HOUR;
  const today = trackingDayKey(now, tz, boundary);
  return weekdayOfKey(today) === 1;
}

function reviewPrompt(weekStart: string, weekEnd: string): string {
  return `Write my weekly review for ${weekStart} to ${weekEnd}.
Use the tools to read everything I logged that week (day summaries, entries and notes, sleep, activity, medicines and any changes, flares) and compare it with the 3 weeks before.
If I logged photos that week, look at the ones that matter (for example stool, skin or urine) and say what changed.
Structure:
- How the week went overall, in 2-3 sentences.
- Symptoms: what was better or worse than usual, with days and numbers.
- Sleep and activity.
- Food, habits and anything that lined up with harder days (say plainly these are not proof of cause).
- Photos, if any.
- Medicines: anything missed or changed.
- 2-4 practical things worth trying or asking my doctor about next week.
Keep it under 450 words.`;
}

export async function generateWeeklyReview(
  userId: string,
  opts: { weekStart?: string; force?: boolean } = {},
): Promise<{ report: IAiWeeklyReportDoc | null; error?: string }> {
  const user = await User.findById(userId).select('preferences').lean();
  if (!user?.preferences?.aiFullAccess) return { report: null, error: 'ai_full_access_off' };

  const tz = resolveTimeZone(user.preferences.timezone);
  const today = trackingDayKey(new Date(), tz, user.preferences.dayBoundaryHour ?? DEFAULT_BOUNDARY_HOUR);
  const week = opts.weekStart ? { weekStart: weekKeyOf(opts.weekStart), weekEnd: shiftDayKey(weekKeyOf(opts.weekStart), 6) } : lastFullWeek(today);

  const uid = new mongoose.Types.ObjectId(userId);
  if (!opts.force) {
    const existing = await AiWeeklyReport.findOne({ userId: uid, weekStart: week.weekStart });
    if (existing) return { report: existing };
  }

  const result = await runAssistant({
    userId, history: [], message: reviewPrompt(week.weekStart, week.weekEnd), budgetMs: REVIEW_BUDGET_MS,
  });
  if (result.error) return { report: null, error: result.error };

  const report = await AiWeeklyReport.findOneAndUpdate(
    { userId: uid, weekStart: week.weekStart },
    { $set: { weekEnd: week.weekEnd, text: result.text } },
    { upsert: true, new: true, setDefaultsOnInsert: true },
  );
  return { report };
}

/** Called by the hourly scheduler; never throws. */
export async function runDueWeeklyReviews(now = new Date(), isDueHour: (prefs: { timezone?: string; dayBoundaryHour?: number } | undefined) => boolean): Promise<number> {
  const users = await User.find({ 'preferences.aiFullAccess': true }).select('preferences').lean();
  let made = 0;
  for (const u of users) {
    try {
      if (!isDueHour(u.preferences) || !isWeeklyReviewDue(u.preferences, now)) continue;
      const { report } = await generateWeeklyReview(String(u._id));
      if (report) made++;
    } catch (err) {
      console.error(`[weeklyReview] failed for ${u._id}:`, err);
    }
  }
  return made;
}
